mapper.select:
select * from (
    select mp.ID, mp.MACHINE_CODE, mp.DOWNTIME_DATE, mp.DOWNTIME_SHIFT,
           mp.DOWNTIME_HOURS, mp.REMARK, mp.IS_DELETE, mp.CREATE_BY, mp.CREATE_TIME,
           mp.UPDATE_BY, mp.UPDATE_TIME,
           mi.MACHINE_NAME
    from T_GSQ_MACHINE_MAINTENANCE_PLAN mp
    left join T_GSQ_MACHINE_INFO mi on mp.MACHINE_CODE = mi.MACHINE_CODE
    where mp.IS_DELETE = '0'

        and mp.DOWNTIME_DATE >= #{downtimeDateBegin}


        and mp.DOWNTIME_DATE <= #{downtimeDateEnd}


        and mp.MACHINE_CODE = #{machineCode}

    order by mp.DOWNTIME_DATE desc, mi.MACHINE_NAME
) t

SELECT count(1)
FROM T_GSQ_MACHINE_MAINTENANCE_PLAN
where IS_DELETE = '0'
and DOWNTIME_DATE = #{downtimeDate}
and MACHINE_CODE = #{machineCode}
and DOWNTIME_SHIFT = #{downtimeShift}
and ID != #{id}
